INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12101, 'នៅក្នុងធរណីមាត្រ តើអ្វីជា «វ៉ិចទ័រ»?', NULL, '["បន្ទាត់ត្រង់គ្មានចំណុចចុង", "ផលធៀបនៃប្រវែងពីរ", "អង្កត់មានទិសដៅដែលមិនគិតពីទីតាំងក្នុងប្លង់", "ចំណុចប្រសព្វនៃបន្ទាត់ពីរ"]', 2, NULL, 1, 'mcq', 'វ៉ិចទ័រ គឺជាអង្កត់ដែលមានទិសដៅច្បាស់លាស់ ដោយមានចំណុចគល់និងចំណុចចុង និងមិនគិតពីទីតាំងក្នុងប្លង់។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12102, 'យោងតាមវិធានត្រីកោណ Chasles ចំពោះបីចំណុច A, B, C តើ \(\vec{AB} + \vec{BC}\) ស្មើនឹងអ្វី?', NULL, '["\\(\\vec{BA}\\)", "\\(\\vec{AC}\\)", "\\(\\vec{CA}\\)", "\\(\\vec{0}\\)"]', 1, NULL, 1, 'mcq', 'តាមវិធានត្រីកោណ Chasles: AB + BC = AC។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12103, 'បើ \(\vec{u} = (x,\, y)\) តើរូបមន្តគណនាប្រវែង (ម៉ូឌុល) \(|\vec{u}|\) គឺជាអ្វី?', NULL, '["\\(|\\vec{u}| = x + y\\)", "\\(|\\vec{u}| = \\sqrt{x + y}\\)", "\\(|\\vec{u}| = \\sqrt{x^2 + y^2}\\)", "\\(|\\vec{u}| = x^2 + y^2\\)"]', 2, NULL, 1, 'mcq', 'ប្រវែងវ៉ិចទ័រក្នុងប្លង់កូអរដោនេគឺ |u| = sqrt(x^2 + y^2)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12104, 'តើរូបមន្តគណនាផលគុណស្កាលែនៃពីរវ៉ិចទ័រ \(\vec{u} = (x_1,\, y_1)\) និង \(\vec{v} = (x_2,\, y_2)\) គឺជាអ្វី?', NULL, '["\\(\\vec{u} \\cdot \\vec{v} = (x_1 + x_2)(y_1 + y_2)\\)", "\\(\\vec{u} \\cdot \\vec{v} = x_1 x_2 + y_1 y_2\\)", "\\(\\vec{u} \\cdot \\vec{v} = x_1 x_2 - y_1 y_2\\)", "\\(\\vec{u} \\cdot \\vec{v} = x_1 y_2 + x_2 y_1\\)"]', 1, NULL, 1, 'mcq', 'ផលគុណស្កាលែតាមកូអរដោនេគឺ u . v = x_1 x_2 + y_1 y_2។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12105, 'តើសញ្ញាណ \(|\vec{AB}|\) តំណាងឱ្យអ្វី?', NULL, '["ផលដកកូអរដោនេ", "ចំណុចកណ្តាលនៃ AB", "ប្រវែង (ម៉ូឌុល) នៃវ៉ិចទ័រ AB", "ទិសដៅពី B ទៅ A"]', 2, NULL, 1, 'mcq', '|AB| ឬ ||AB|| គឺជាប្រវែង ឬម៉ូឌុលនៃវ៉ិចទ័រ ដែលជាចម្ងាយរវាងចំណុចគល់ A និងចំណុចចុង B។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12106, 'គណនាផលបូកវ៉ិចទ័រ ៖ \(\vec{MN} + \vec{NP} + \vec{PM}\)', NULL, '["\\(\\vec{0}\\)", "\\(3\\)", "\\(\\vec{MP}\\)", "\\(2\\vec{MN}\\)"]', 0, NULL, 1, 'mcq', 'MN + NP + PM = MP + PM = MM = 0 (វ៉ិចទ័រសូន្យ)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
