INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12107, 'ពិនិត្យរូបភាពកូអរដោនេខាងក្រោម។ តើវ៉ិចទ័រ \(\vec{u}\) មានកូអរដោនេស្មើនឹងប៉ុន្មាន?', 'g10-36c0e32906.svg', '["\\((4,\\, -3)\\)", "\\((4,\\, 3)\\)", "\\((7,\\, 1) Wandering\\)", "\\((3,\\, 4)\\)"]', 1, NULL, 1, 'mcq', 'ចំណុច P មានកូអរដោនេ (4, 3) នាំឱ្យវ៉ិចទ័រ OP = u = 4i + 3j = (4, 3)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12108, 'តើវ៉ិចទ័រពីរ \(\vec{u}\) និង \(\vec{v}\) ស្មើគ្នា (\(\vec{u} = \vec{v}\)) លុះត្រាតែមានលក្ខខណ្ឌណា?', NULL, '["វាមានតែទិសស្របគ្នាតែប៉ុណ្ណោះ", "វាមានចំណុចគល់ដូចគ្នា", "វាមានតែប្រវែងស្មើគ្នាតែប៉ុណ្ណោះ", "វាមានទិសដៅដូចគ្នា និងមានប្រវែងស្មើគ្នា"]', 3, NULL, 1, 'mcq', 'វ៉ិចទ័រពីរស្មើគ្នាលុះត្រាតែវាមានទិសស្របគ្នា ទិសដៅដូចគ្នា និងប្រវែងស្មើគ្នា។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
