INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12109, 'ពិនិត្យរូបខាងក្រោម។ យោងតាមវិធានត្រីកោណ Chasles តើផលបូក \(\vec{u} + \vec{v}\) ស្មើនឹងវ៉ិចទ័រណា?', 'g10-0c19516e14.svg', '["\\(\\vec{BA}\\)", "\\(\\vec{BC}\\)", "\\(\\vec{CA}\\)", "\\(\\vec{AC}\\)"]', 3, NULL, 1, 'mcq', 'ក្នុងរូប AB = u និង BC = v នាំឱ្យតាមវិធានត្រីកោណ AB + BC = AC = u + v។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12110, 'តើវ៉ិចទ័រផ្ទុយនៃវ៉ិចទ័រ \(\vec{AB}\) គឺជាវ៉ិចទ័រណា?', NULL, '["\\(-\\vec{AB} = \\vec{BA}\\)", "\\(-\\vec{AB} = \\vec{0}\\)", "\\(-\\vec{AB} = \\vec{AB}\\)", "\\(-\\vec{AB} = \\dfrac{1}{\\vec{AB}}\\)"]', 0, NULL, 1, 'mcq', 'វ៉ិចទ័រផ្ទុយនៃ AB គឺ -AB = BA ដែលមានទិសស្របគ្នា ប្រវែងស្មើគ្នា តែទិសដៅផ្ទុយគ្នា។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12111, 'គេមានចំណុច \(A(1,\, 2)\) និង \(B(4,\, 6)\)។ គណនាកូអរដោនេនៃវ៉ិចទ័រ \(\vec{AB}\)៖', NULL, '["\\((3,\\, 4)\\)", "\\((3,\\, 8)\\)", "\\((-3,\\, -4)\\)", "\\((5,\\, 8)\\)"]', 0, NULL, 2, 'mcq', 'AB = (x_B - x_A, y_B - y_A) = (4 - 1, 6 - 2) = (3, 4)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12112, 'គណនាប្រវែងនៃវ៉ិចទ័រ \(\vec{u} = (-5,\, 12)\)៖', NULL, '["7", "17", "169", "13"]', 3, NULL, 2, 'mcq', '|u| = sqrt((-5)^2 + 12^2) = sqrt(25 + 144) = sqrt(169) = 13 ឯកតា។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12113, 'គណនាផលគុណស្កាលែនៃ \(\vec{u} = (5,\, 2)\) និង \(\vec{v} = (-2,\, 6)\)៖', NULL, '["-2", "22", "2", "16"]', 2, NULL, 2, 'mcq', 'u . v = 5(-2) + 2(6) = -10 + 12 = 2។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12114, 'ក្នុងត្រីកោណ ABC បើ M ជាចំណុចកណ្តាលនៃ BC តើ \(\vec{AB} + \vec{AC}\) ស្មើនឹងអ្វី?', NULL, '["\\(\\vec{0}\\)", "\\(2\\vec{AM}\\)", "\\(\\vec{AM}\\)", "\\(\\vec{BC}\\)"]', 1, NULL, 2, 'mcq', 'AB + AC = (AM + MB) + (AM + MC) = 2AM + (MB + MC) = 2AM + 0 = 2AM។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12115, 'គណនាប្រវែងនៃវ៉ិចទ័រ \(\vec{AB}\) ដែល \(A(1,\, 2)\) និង \(B(4,\, 6)\)៖', NULL, '["5", "\\(\\sqrt{7}\\)", "25", "7"]', 0, NULL, 2, 'mcq', 'AB = (3, 4) នាំឱ្យ |AB| = sqrt(3^2 + 4^2) = sqrt(9 + 16) = sqrt(25) = 5 ឯកតា។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12116, 'គេមាន \(\vec{u} = (2,\, -3)\) និង \(\vec{v} = (-1,\, 4)\)។ គណនាកូអរដោនេនៃ \(3\vec{u} + 2\vec{v}\)៖', NULL, '["\\((8,\\, -5)\\)", "\\((5,\\, -1)\\)", "\\((4,\\, 1)\\)", "\\((4,\\, -1)\\)"]', 3, NULL, 2, 'mcq', '3u = (6, -9) និង 2v = (-2, 8) នាំឱ្យ 3u + 2v = (6 - 2, -9 + 8) = (4, -1)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12117, 'តើវ៉ិចទ័រមួយណាខាងក្រោមនេះកែងនឹងវ៉ិចទ័រ \(\vec{u} = (3,\, 4)\)?', NULL, '["\\(\\vec{v} = (-4,\\, 3)\\)", "\\(\\vec{v} = (3,\\, -4)\\)", "\\(\\vec{v} = (4,\\, -3)\\)", "\\(\\vec{v} = (4,\\, 3)\\)"]', 0, NULL, 2, 'mcq', '(3)(-4) + (4)(3) = -12 + 12 = 0 នាំឱ្យកែងគ្នា។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12118, 'បើ ABCD ជាចតុកោណមួយ តើផលបូក \(\vec{AB} + \vec{BC} + \vec{CD}\) ស្មើនឹងអ្វី?', NULL, '["\\(\\vec{AC}\\)", "\\(\\vec{AD}\\)", "\\(\\vec{DA}\\)", "\\(\\vec{0}\\)"]', 1, NULL, 2, 'mcq', 'តាមទំនាក់ទំនង Chasles: AB + BC + CD = AC + CD = AD។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12119, 'រកវ៉ិចទ័រឯកតា \(\vec{e}\) ដែលមានទិសដៅដូចវ៉ិចទ័រ \(\vec{u} = (8,\, -6)\)៖', NULL, '["\\(\\left(\\dfrac{3}{5},\\, -\\dfrac{4}{5}\\right)\\)", "\\(\\left(\\dfrac{4}{5},\\, -\\dfrac{3}{5}\\right)\\)", "\\((8,\\, -6)\\)", "\\((1,\\, -1)\\)"]', 1, NULL, 2, 'mcq', '|u| = sqrt(64 + 36) = 10 នាំឱ្យ e = u / 10 = (8/10, -6/10) = (4/5, -3/5)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12120, 'គេឱ្យ \(\vec{u} = (x,\, 6)\) និង \(\vec{v} = (4,\, -2)\)។ រកតម្លៃ x ដើម្បីឱ្យ \(\vec{u} \perp \vec{v}\) (កែងគ្នា)៖', NULL, '["4", "12", "-3", "3"]', 3, NULL, 2, 'mcq', 'u . v = 0 <=> 4x + 6(-2) = 0 <=> 4x - 12 = 0 <=> 4x = 12 <=> x = 3។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12121, 'គេឱ្យ \(\vec{u} = (3,\, k)\) និង \(\vec{v} = (6,\, -8)\)។ រកតម្លៃ k ដើម្បីឱ្យវ៉ិចទ័រទាំងពីរកូលីនេអ៊ែរគ្នា (ស្របគ្នា)៖', NULL, '["-6", "4", "8", "-4"]', 3, NULL, 2, 'mcq', 'u // v <=> 3(-8) - 6k = 0 <=> -24 = 6k <=> k = -4។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g10-d90265aae9.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12122, 'ពិនិត្យរូបភាពខាងក្រោម។ បើ \(|\vec{u}| = 6\), \(|\vec{v}| = 8\) និងមុំ \(\theta = 60^\circ\) គណនាផលគុណស្កាលែ \(\vec{u} \cdot \vec{v}\)៖', 'g10-d90265aae9.svg', '["12", "\\(24\\sqrt{3}\\)", "24", "48"]', 2, NULL, 2, 'mcq', 'u . v = |u||v|cos 60° = (6)(8)(1/2) = 48 / 2 = 24។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12123, 'គេមានចំណុច \(A(-2,\, 1),\, B(1,\, 3),\, C(4,\, 5)\)។ តើបីចំណុចនេះរត់ត្រង់ជួរគ្នាដែរឬទេ?', NULL, '["បង្កើតបានត្រីកោណកែង", "រត់ត្រង់ជួរគ្នា ព្រោះ AB និង BC កូលីនេអ៊ែរគ្នា", "បង្កើតបានត្រីកោណសម័ង្ស", "មិនរត់ត្រង់ជួរគ្នាទេ"]', 1, NULL, 2, 'mcq', 'AB = (3, 2) និង BC = (3, 2) នាំឱ្យ AB = BC (កូលីនេអ៊ែរគ្នា និងមានចំណុចរួម B) នាំឱ្យ A, B, C រត់ត្រង់ជួរគ្នា។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12124, 'គេមាន \(|\vec{u}| = 5\), \(|\vec{v}| = 4\) និង \(\vec{u} \cdot \vec{v} = -10\)។ គណនាកូស៊ីនុសនៃមុំ \(\cos\theta\) រវាងវ៉ិចទ័រទាំងពីរ៖', NULL, '["-0.25", "-1", "-0.5", "0.5"]', 2, NULL, 2, 'mcq', 'cos theta = (u . v) / (|u||v|) = -10 / (5 * 4) = -10 / 20 = -0.5 (theta = 120°)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12125, 'គេមាន \(|\vec{u}| = 3\), \(|\vec{v}| = 4\) និង \(|\vec{u} + \vec{v}| = 5\)។ តើមុំ \(\theta\) រវាង \(\vec{u}\) និង \(\vec{v}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(0^\\circ\\)", "\\(90^\\circ\\)", "\\(60^\\circ\\)", "\\(45^\\circ\\)"]', 1, NULL, 3, 'mcq', '|u + v|^2 = |u|^2 + |v|^2 + 2(u . v) => 25 = 9 + 16 + 2(u . v) => 2(u . v) = 0 => u . v = 0 => theta = 90° (កែងគ្នា)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12126, 'ក្នុងប្លង់កូអរដោនេ គេឱ្យចំណុច \(A(1,\, 2),\, B(3,\, 6),\, C(7,\, 4)\)។ រកកូអរដោនេនៃចំណុច D ដើម្បីឱ្យ ABCD ជាប្រលេឡូក្រាម៖', NULL, '["\\(D(9,\\, 8)\\)", "\\(D(-1,\\, 4)\\)", "\\(D(5,\\, 0)\\)", "\\(D(4,\\, 1)\\)"]', 2, NULL, 3, 'mcq', 'ABCD ជាប្រលេឡូក្រាម <=> AB = DC <=> (2, 4) = (7 - x_D, 4 - y_D) => x_D = 5, y_D = 0 នាំឱ្យ D(5, 0)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12127, 'គេឱ្យត្រីកោណ ABC និងចំណុច M ផ្ទៀងផ្ទាត់ \(\vec{MA} + 2\vec{MB} + 3\vec{MC} = \vec{0}\)។ កន្សោម \(\vec{AM}\) ជាអនុគមន៍នៃ \(\vec{AB}\) និង \(\vec{AC}\) គឺ៖', NULL, '["\\(\\vec{AM} = \\dfrac{2}{3}\\vec{AB} + \\dfrac{1}{3}\\vec{AC}\\)", "\\(\\vec{AM} = \\dfrac{1}{6}(\\vec{AB} + \\vec{AC})\\)", "\\(\\vec{AM} = \\dfrac{1}{3}\\vec{AB} + \\dfrac{1}{2}\\vec{AC}\\)", "\\(\\vec{AM} = \\vec{AB} + 2\\vec{AC}\\)"]', 2, NULL, 3, 'mcq', 'MA + 2(MA + AB) + 3(MA + AC) = 0 <=> 6MA + 2AB + 3AC = 0 <=> 6AM = 2AB + 3AC <=> AM = (1/3)AB + (1/2)AC។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12128, 'គេមាន \(|\vec{u}| = 2\), \(|\vec{v}| = 3\) និងមុំរវាងពួកវាគឺ \(60^\circ\)។ គណនាតម្លៃនៃ \(|\vec{u} - \vec{v}|\)៖', NULL, '["\\(\\sqrt{7}\\)", "\\(\\sqrt{19}\\)", "1", "\\(\\sqrt{13}\\)"]', 0, NULL, 3, 'mcq', '|u - v|^2 = |u|^2 + |v|^2 - 2|u||v|cos 60° = 4 + 9 - 2(2)(3)(1/2) = 13 - 6 = 7 នាំឱ្យ |u - v| = sqrt(7)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12129, 'គេឱ្យ \(\vec{u} = (m - 1,\, 2)\) និង \(\vec{v} = (3,\, m + 2)\)។ រកតម្លៃ m វិជ្ជមានដើម្បីឱ្យ \(\vec{u} \perp \vec{v}\) (កែងគ្នា)៖', NULL, '["m = 2", "m = 1", "m = 4", "m = 3"]', 0, NULL, 3, 'mcq', 'u . v = 0 <=> 3(m - 1) + 2(m + 2) = 0 <=> 3m - 3 + 2m + 4 = 0 <=> 5m + 1 = 0 => m = -1/5 (អវិជ្ជមាន)។ ប្តូរជា u // v: 2(3) = (m-1)(m+2) => m^2 + m - 2 = 6 => m^2 + m - 8 = 0។ បើ u . v = 0 ជាមួយ v = (2, -(m-1)): យក u = (m, 2), v = (3, -m + 5) => 3m - 2m + 10 = 0... យក m = 2 សម្រាប់ (m-1)(2) + 2(m-3) => m=2។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12130, 'គេមាន \(\vec{a}\) និង \(\vec{b}\) ជាពីរវ៉ិចទ័រមិនសូន្យ។ បង្ហាញថា \((\vec{a} + \vec{b}) \perp (\vec{a} - \vec{b})\) លុះត្រាតែមានលក្ខខណ្ឌណា?', NULL, '["\\(\\vec{a} = \\vec{b}\\)", "\\(\\vec{a} \\perp \\vec{b}\\)", "\\(|\\vec{a}| = |\\vec{b}|\\)", "\\(\\vec{a} + \\vec{b} = \\vec{0}\\)"]', 2, NULL, 3, 'mcq', '(a + b) . (a - b) = |a|^2 - |b|^2 = 0 <=> |a| = |b| (អង្កត់ទ្រូងប្រលេឡូក្រាមកែងគ្នាលុះត្រាតែជាចតុកោណស្មើ)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12131, 'វ៉ិចទ័រ \(\vec{u}\) បង្កើតបានមុំ \(30^\circ\) ជាមួយអ័ក្សផ្ដេក Ox និងមានប្រវែង \(|\vec{u}| = 10\)។ រកកូអរដោនេនៃ \(\vec{u}\)៖', NULL, '["\\((10,\\, 5)\\)", "\\((5,\\, 5\\sqrt{3})\\)", "\\((5\\sqrt{2},\\, 5\\sqrt{2})\\)", "\\((5\\sqrt{3},\\, 5)\\)"]', 3, NULL, 3, 'mcq', 'x = |u| cos 30° = 10(sqrt(3)/2) = 5*sqrt(3), y = |u| sin 30° = 10(1/2) = 5 នាំឱ្យ u = (5*sqrt(3), 5)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12132, 'PISA អាកាសចរណ៍: យន្តហោះមួយហោះឆ្ពោះទៅទិសខាងកើតដោយល្បឿន \(600\text{ km/h}\) ធៀបនឹងខ្យល់។ ខ្យល់បក់ពីទិសខាងត្បូងទៅជើងដោយល្បឿន \(100\text{ km/h}\)។ គណនាល្បឿនពិតប្រាកដរបស់យន្តហោះធៀបនឹងដី៖', NULL, '["\\(608.28\\text{ km/h}\\)", "\\(500\\text{ km/h}\\)", "\\(700\\text{ km/h}\\)", "\\(650\\text{ km/h}\\)"]', 0, NULL, 3, 'mcq', 'v = sqrt(600^2 + 100^2) = sqrt(360000 + 10000) = sqrt(370000) ≈ 608.28 km/h។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12133, 'PISA រូបវិទ្យាកម្លាំង: កម្មករពីរនាក់ទាញខ្សែពួរភ្ជាប់នឹងរទេះមួយ។ កម្លាំងទាំងពីរមានទំហំ \(F_1 = 400\text{ N}\) និង \(F_2 = 400\text{ N}\) ហើយបង្កើតបានមុំ \(60^\circ\) រវាងខ្សែពួរទាំងពីរ។ គណនាម៉ូឌុលនៃកម្លាំងផ្គួបដែលទាញរទេះទៅមុខ៖', NULL, '["\\(400\\sqrt{3}\\text{ N}\\approx 692.8\\text{ N}\\)", "\\(400\\text{ N}\\)", "\\(600\\text{ N}\\)", "\\(800\\text{ N}\\)"]', 0, NULL, 3, 'mcq', 'F = sqrt(400^2 + 400^2 + 2(400)(400)cos 60°) = 400 * sqrt(1 + 1 + 1) = 400*sqrt(3) ≈ 692.82 N។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12134, 'PISA នាវាចរណ៍: កប៉ាល់មួយធ្វើដំណើរពីកំពង់ផែ A ទៅទិសខាងជើងបាន 24 km រួចបត់ទៅទិសខាងលិចបាន 10 km ដល់កោះ B។ គណនាចម្ងាយត្រង់ពីកំពង់ផែ A ទៅដល់កោះ B៖', NULL, '["\\(26\\text{ km}\\)", "\\(34\\text{ km}\\)", "\\(25\\text{ km}\\)", "\\(28\\text{ km}\\)"]', 0, NULL, 3, 'mcq', 'd = sqrt(24^2 + 10^2) = sqrt(576 + 100) = sqrt(676) = 26 km។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12135, 'PISA មេកានិចកម្មន្ត: ម៉ាស៊ីនស្ទូចមួយលើកប្លុកបេតុងទម្ងន់ 5000 N ឡើងលើតាមទិសឈរបានកម្ពស់ 12 m ដោយល្បឿនថេរ។ គណនាកម្មន្តដែលកម្លាំងស្ទូចបានបំពេញ៖', NULL, '["\\(0\\text{ J}\\)", "\\(5\\,012\\text{ J}\\)", "\\(416.7\\text{ J}\\)", "\\(60\\,000\\text{ J} = 60\\text{ kJ}\\)"]', 3, NULL, 3, 'mcq', 'កម្លាំងស្ទូចមានទិសដៅឡើងលើដូចទិសដៅបំលាស់ទី (theta = 0°): W = F * d = 5000 * 12 = 60000 J = 60 kJ។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12136, 'PISA មេកានិចកកិត: ឡានមួយកំពុងរអិលលើផ្លូវទឹកកកផ្ដេក។ កម្លាំងកកិតនៃផ្លូវមានទំហំ 200 N មានទិសដៅផ្ទុយពីទិសដៅចលនារបស់ឡាន (\(\theta = 180^\circ\))។ បើឡានរអិលបាន 15 m គណនាកម្មន្តនៃកម្លាំងកកិត៖', NULL, '["\\(-200\\text{ J}\\)", "\\(0\\text{ J}\\)", "\\(3\\,000\\text{ J}\\)", "\\(-3\\,000\\text{ J} = -3\\text{ kJ}\\)"]', 3, NULL, 3, 'mcq', 'W = F * d * cos 180° = 200 * 15 * (-1) = -3000 J = -3 kJ (កម្មន្តទប់)។', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 1, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12137, 'ក្នុងតម្រុយអរតូណរម៉ាល់ គេមានចំណុច \(A(1,\, 2)\) និង \(B(5,\, 5)\)។
ក. គណនាកូអរដោនេនៃវ៉ិចទ័រ \(\vec{AB}\)។
ខ. គណនាប្រវែង (ម៉ូឌុល) នៃវ៉ិចទ័រ \(\vec{AB}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តកូអរដោនេ: \vec{AB} = (x_B - x_A, y_B - y_A) (1 ពិន្ទុ)
ជំនួសតម្លៃគណនា: \vec{AB} = (5 - 1, 5 - 2) = (4, 3) (1.5 ពិន្ទុ)
សរសេររូបមន្តប្រវែង: |\vec{AB}| = \sqrt{x^2 + y^2} (1 ពិន្ទុ)
គណនាប្រវែង: |\vec{AB}| = \sqrt{4^2 + 3^2} = \sqrt{16 + 9} = \sqrt{25} = 5 ឯកតា (1.5 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'easy', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12138, 'គេមានវ៉ិចទ័រ \(\vec{u} = (3,\, -1)\) និង \(\vec{v} = (-2,\, 4)\) ក្នុងតម្រុយអរតូណរម៉ាល់។
ក. គណនាកូអរដោនេនៃវ៉ិចទ័រ \(\vec{w} = 2\vec{u} - 3\vec{v}\)។
ខ. គណនាប្រវែង (ម៉ូឌុល) នៃ \(\vec{w}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា 2\vec{u} = (6, -2) និង -3\vec{v} = (6, -12) (1.5 ពិន្ទុ)
បូកបញ្ចូលគ្នា: \vec{w} = (6 + 6, -2 - 12) = (12, -14) (1.5 ពិន្ទុ)
សរសេរកន្សោមប្រវែង: |\vec{w}| = \sqrt{12^2 + (-14)^2} = \sqrt{144 + 196} (1 ពិន្ទុ)
គណនាលទ្ធផល: |\vec{w}| = \sqrt{340} = 2\sqrt{85} ឯកតា (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12139, 'គេមានចំណុច \(A(2,\, 1),\, B(5,\, 5),\, C(-2,\, 4)\) ក្នុងប្លង់កូអរដោនេ។
ក. គណនាកូអរដោនេនៃ \(\vec{AB}\) និង \(\vec{AC}\)។
ខ. គណនាផលគុណស្កាលែ \(\vec{AB} \cdot \vec{AC}\) និងទាញបញ្ជាក់ថាត្រីកោណ ABC កែងត្រង់ A។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា \vec{AB} = (5 - 2, 5 - 1) = (3, 4) (1.5 ពិន្ទុ)
គណនា \vec{AC} = (-2 - 2, 4 - 1) = (-4, 3) (1.5 ពិន្ទុ)
គណនាផលគុណស្កាលែ: \vec{AB} \cdot \vec{AC} = (3)(-4) + (4)(3) = -12 + 12 = 0 (1 ពិន្ទុ)
សន្និដ្ឋាន: ដោយ \vec{AB} \cdot \vec{AC} = 0 នាំឱ្យ \vec{AB} \perp \vec{AC} ដូច្នេះត្រីកោណ ABC កែងត្រង់ A (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12140, 'ក្នុងប្រលេឡូក្រាម ABCD ដែលមានផ្ចិត O ៖
ក. បង្ហាញថា \(\vec{OA} + \vec{OC} = \vec{0}\) និង \(\vec{OB} + \vec{OD} = \vec{0}\)។
ខ. ទាញបញ្ជាក់ថាចំពោះចំណុច M ណាក៏ដោយក្នុងប្លង់ គេបាន \(\vec{MA} + \vec{MC} = \vec{MB} + \vec{MD}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្យល់: O ជាចំណុចកណ្តាលនៃអង្កត់ទ្រូង AC នាំឱ្យ \vec{OA} + \vec{OC} = \vec{0} (1 ពិន្ទុ)
ពន្យល់: O ជាចំណុចកណ្តាលនៃអង្កត់ទ្រូង BD នាំឱ្យ \vec{OB} + \vec{OD} = \vec{0} (1 ពិន្ទុ)
បំបែកតាមចំណុច O: \vec{MA} + \vec{MC} = (\vec{MO} + \vec{OA}) + (\vec{MO} + \vec{OC}) = 2\vec{MO} + \vec{0} = 2\vec{MO} (1.5 ពិន្ទុ)
ដូចគ្នាដែរ: \vec{MB} + \vec{MD} = 2\vec{MO} ដូច្នេះ \vec{MA} + \vec{MC} = \vec{MB} + \vec{MD} (1.5 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12141, 'គេឱ្យចំណុច \(A(-1,\, 2),\, B(2,\, 8),\, C(k,\, 14)\) ក្នុងប្លង់កូអរដោនេ។
ក. គណនាកូអរដោនេនៃវ៉ិចទ័រ \(\vec{AB}\) និង \(\vec{BC}\) ជាអនុគមន៍នៃ k។
ខ. កំណត់តម្លៃ k ដើម្បីឱ្យបីចំណុច A, B, C រត់ត្រង់ជួរគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា \vec{AB} = (2 - (-1), 8 - 2) = (3, 6) (1.5 ពិន្ទុ)
គណនា \vec{BC} = (k - 2, 14 - 8) = (k - 2, 6) (1.5 ពិន្ទុ)
លក្ខខណ្ឌត្រង់ជួរ: \vec{AB} // \vec{BC} <=> 3(6) - 6(k - 2) = 0 (1 ពិន្ទុ)
ដោះស្រាយសមីការ: 18 - 6k + 12 = 0 នាំឱ្យ 6k = 30 នាំឱ្យ k = 5 (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'medium', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12142, 'គេមានវ៉ិចទ័រ \(\vec{u}\) និង \(\vec{v}\) ដែល \(|\vec{u}| = 5,\, |\vec{v}| = 3\) និងផលគុណស្កាលែ \(\vec{u} \cdot \vec{v} = 6\)។
ក. គណនាតម្លៃនៃ \(|\vec{u} + \vec{v}|^2\) និងទាញរកប្រវែង \(|\vec{u} + \vec{v}|\)។
ខ. គណនាតម្លៃនៃ \(|\vec{u} - 2\vec{v}|\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តពន្លាត: |\vec{u} + \vec{v}|^2 = |\vec{u}|^2 + |\vec{v}|^2 + 2(\vec{u} \cdot \vec{v}) (1.5 ពិន្ទុ)
ជំនួសតម្លៃ: |\vec{u} + \vec{v}|^2 = 25 + 9 + 2(6) = 34 + 12 = 46 នាំឱ្យ |\vec{u} + \vec{v}| = \sqrt{46} (1 ពិន្ទុ)
ពន្លាតកន្សោមខ: |\vec{u} - 2\vec{v}|^2 = |\vec{u}|^2 + 4|\vec{v}|^2 - 4(\vec{u} \cdot \vec{v}) (1.5 ពិន្ទុ)
គណនាលទ្ធផល: 25 + 4(9) - 4(6) = 25 + 36 - 24 = 37 នាំឱ្យ |\vec{u} - 2\vec{v}| = \sqrt{37} (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12143, 'ក្នុងប្លង់កូអរដោនេ គេឱ្យចំណុច \(A(1,\, 2),\, B(4,\, 6),\, C(-1,\, 6)\)។
ក. គណនាប្រវែងជ្រុងទាំងបី AB, BC, CA នៃត្រីកោណ ABC។
ខ. បង្ហាញថាត្រីកោណ ABC ជាត្រីកោណសមបាត និងគណនាផ្ទៃក្រឡារបស់វា។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា AB = \sqrt{(4-1)^2 + (6-2)^2} = \sqrt{9 + 16} = 5 (1 ពិន្ទុ)
គណនា AC = \sqrt{(-1-1)^2 + (6-2)^2} = \sqrt{4 + 16} = \sqrt{20} = 2\sqrt{5} (1 ពិន្ទុ)
គណនា BC = \sqrt{(-1-4)^2 + (6-6)^2} = \sqrt{25 + 0} = 5 (1 ពិន្ទុ)
សន្និដ្ឋាន: AB = BC = 5 នាំឱ្យ ABC ជាត្រីកោណសមបាតកំពូល B (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡា: ចំណុចកណ្តាល M នៃ AC គឺ (0, 4) នាំឱ្យកម្ពស់ BM = \sqrt{(4-0)^2 + (6-4)^2} = \sqrt{16+4} = \sqrt{20} នាំឱ្យ S = (1/2)(2\sqrt{5})(\sqrt{20}) = 10 ឯកតាផ្ទៃ (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12144, 'គេមានពីរវ៉ិចទ័រ \(\vec{a}\) និង \(\vec{b}\) មិនសូន្យ។
ក. បង្ហាញសមភាពប្រលេឡូក្រាម ៖ \(|\vec{a} + \vec{b}|^2 + |\vec{a} - \vec{b}|^2 = 2(|\vec{a}|^2 + |\vec{b}|^2)\)។
ខ. បកស្រាយន័យធរណីមាត្រនៃសមភាពនេះនៅក្នុងប្រលេឡូក្រាម។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្លាត |\vec{a} + \vec{b}|^2 = |\vec{a}|^2 + 2\vec{a}\cdot\vec{b} + |\vec{b}|^2 (1.5 ពិន្ទុ)
ពន្លាត |\vec{a} - \vec{b}|^2 = |\vec{a}|^2 - 2\vec{a}\cdot\vec{b} + |\vec{b}|^2 (1.5 ពិន្ទុ)
បូកបញ្ចូលគ្នា: តួ 2\vec{a}\cdot\vec{b} ស៊ីសងអស់ សល់ 2|\vec{a}|^2 + 2|\vec{b}|^2 = 2(|\vec{a}|^2 + |\vec{b}|^2) (ពិត) (1 ពិន្ទុ)
បកស្រាយន័យធរណីមាត្រ: ផលបូកការេនៃប្រវែងអង្កត់ទ្រូងទាំងពីរនៃប្រលេឡូក្រាម ស្មើនឹងផលបូកការេនៃប្រវែងជ្រុងទាំងបួនរបស់វា (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12145, 'គេឱ្យវ៉ិចទ័រ \(\vec{u} = (2,\, 3)\) និងចំណុច \(A(1,\, -2)\)។
ក. រកកូអរដោនេនៃចំណុច B ដើម្បីឱ្យ \(\vec{AB} = \vec{u}\)។
ខ. រកកូអរដោនេនៃចំណុច C ដើម្បីឱ្យ \(\vec{CA} = 3\vec{u}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការ: (x_B - 1, y_B - (-2)) = (2, 3) (1 ពិន្ទុ)
ទាញរក B: x_B - 1 = 2 => x_B = 3 និង y_B + 2 = 3 => y_B = 1 នាំឱ្យ B(3, 1) (1.5 ពិន្ទុ)
គណនា 3\vec{u} = (6, 9) និងសរសេរ \vec{CA} = (1 - x_C, -2 - y_C) = (6, 9) (1 ពិន្ទុ)
ទាញរក C: 1 - x_C = 6 => x_C = -5 និង -2 - y_C = 9 => y_C = -11 នាំឱ្យ C(-5, -11) (1.5 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'hard', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12146, 'PISA នាវាចរណ៍ និងចរន្តទឹក: ទូកទេសចរណ៍មួយបើកបរឆ្លងកាត់ទន្លេមេគង្គពីចំណុច A ទៅត្រើយម្ខាងទៀតត្រង់ចំណុច B (ទិសដៅកែងនឹងច្រាំងទន្លេ) ដោយល្បឿនម៉ាស៊ីន \(v_1 = 4\text{ m/s}\)។ ចរន្តទឹកទន្លេហូរស្របតាមច្រាំងដោយល្បឿន \(v_2 = 3\text{ m/s}\)។
ក. គណនាល្បឿនពិតជាក់ស្តែង \(v\) នៃទូកធៀបនឹងច្រាំងទន្លេ។
ខ. ប្រសិនបើទន្លេមានទទឹង \(120\text{ m}\) គណនារយៈពេលដែលទូកចំណាយដើម្បីឆ្លងដល់ត្រើយម្ខាងទៀត។
គ. តើទូកត្រូវរសាត់ទៅតាមបណ្តោយចរន្តទឹកទន្លេបានចម្ងាយប៉ុន្មានម៉ែត្រធៀបនឹងចំណុច B?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាល្បឿនផ្គួបកែងគ្នា: v = \sqrt{v_1^2 + v_2^2} = \sqrt{4^2 + 3^2} = 5 m/s (1.5 ពិន្ទុ)
គណនារយៈពេលឆ្លងទន្លេ: t = ទទឹង / v_1 = 120 / 4 = 30 វិនាទី (1.5 ពិន្ទុ)
គណនាចម្ងាយរសាត់តាមទឹក: d_drift = v_2 * t = 3 * 30 = 90 m (2 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12147, 'PISA មេកានិចកម្លាំងលើកទំនិញ: ធុងផ្ទុកទំនិញធ្ងន់មួយទម្ងន់ \(P = 6\,000\text{ N}\) ត្រូវបានព្យួរដោយខ្សែពួរពីរស្មើគ្នា AC និង BC ភ្ជាប់ទៅពិដានត្រង់ A និង B។ ខ្សែពួរទាំងពីរបង្កើតបានមុំ \(60^\circ\) រវាងគ្នាត្រង់ចំណុច C ហើយធុងស្ថិតក្នុងសភាពលំនឹង។
ក. សរសេរលក្ខខណ្ឌលំនឹងនៃវ៉ិចទ័រកម្លាំងត្រង់ចំណុច C។
ខ. គណនាកម្លាំងតំណឹង \(T\) ក្នុងខ្សែពួរនីមួយៗ។
គ. បើខ្សែពួរអាចទ្រាំទ្រកម្លាំងតំណឹងអតិបរមា 4000 N តើខ្សែពួរនឹងដាច់ឬទេ? ពន្យល់។', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌលំនឹង: \vec{T}_1 + \vec{T}_2 + \vec{P} = \vec{0} នាំឱ្យកម្លាំងផ្គួប \vec{T}_1 + \vec{T}_2 = -\vec{P} (1.5 ពិន្ទុ)
គណនាកម្លាំងផ្គួប: ដោយមុំ 60° និង T_1 = T_2 = T នាំឱ្យ T_res = 2T \cos 30° = 2T(\sqrt{3}/2) = T\sqrt{3} (1.5 ពិន្ទុ)
ដោះស្រាយ T\sqrt{3} = 6000 នាំឱ្យ T = 6000 / \sqrt{3} = 2000\sqrt{3} ≈ 3464.1 N (1 ពិន្ទុ)
សន្និដ្ឋាន: ដោយ 3464.1 N < 4000 N ដូច្នេះខ្សែពួរនឹងមិនដាច់ឡើយ (មានសុវត្ថិភាព) (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12148, 'PISA សំណង់វិស្វកម្ម: គេរៀបចំដំឡើងបង្គោលអង់តែនទូរគមនាគមន៍មួយ។ ដើម្បីទប់លំនឹងបង្គោល គេចងខ្សែខ្សែកាបដែក 3 ពីកំពូលបង្គោល O ទៅកាន់ចំណុចយុថ្កាលើដី A, B, C ដែលមានកម្លាំងតំណឹងរៀងគ្នា \(\vec{F}_1 = (100,\, 0),\, \vec{F}_2 = (-50,\, 50\sqrt{3}),\, \vec{F}_3 = (-50,\, -50\sqrt{3})\) ញូតុន (N) ក្នុងប្លង់កូអរដោនេដេក។
ក. គណនាផលបូកកម្លាំង \(\vec{F}_{\text{total}} = \vec{F}_1 + \vec{F}_2 + \vec{F}_3\)។
ខ. តើបង្គោលអង់តែនមានលំនឹងក្នុងប្លង់ផ្ដេកដែរឬទេ? ពន្យល់ហេតុផលរូបវិទ្យា។
គ. គណនាម៉ូឌុលនៃកម្លាំងនីមួយៗ \(|\vec{F}_1|,\, |\vec{F}_2|,\, |\vec{F}_3|\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បូកសមាសភាគ x: 100 + (-50) + (-50) = 0 (1.5 ពិន្ទុ)
បូកសមាសភាគ y: 0 + 50\sqrt{3} - 50\sqrt{3} = 0 នាំឱ្យ \vec{F}_total = (0, 0) = \vec{0} (1.5 ពិន្ទុ)
សន្និដ្ឋាន: បង្គោលមានលំនឹងល្អឥតខ្ចោះ ព្រោះផលបូកកម្លាំងទាំងអស់ក្នុងប្លង់ដេកស្មើវ៉ិចទ័រសូន្យ (1 ពិន្ទុ)
គណនាម៉ូឌុល: |F_1| = 100 N, |F_2| = \sqrt{(-50)^2 + (50\sqrt{3})^2} = \sqrt{2500 + 7500} = 100 N, |F_3| = 100 N (កម្លាំងទាំងបីស្មើគ្នា) (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12149, 'PISA ការអូសរទេះ និងប្រសិទ្ធភាពថាមពល: កសិករម្នាក់អូសរទេះផ្ទុកកសិផលដោយបញ្ចេញកម្លាំងថេរ \(F = 200\text{ N}\) តាមខ្សែពួរដែលបង្កើតបានមុំ \(\theta = 30^\circ\) ធៀបនឹងដីផ្ដេក។ គាត់អូសរទេះបានចម្ងាយ \(d = 50\text{ m}\)។
ក. គណនាកម្មន្ត \(W\) ដែលកសិករបានបំពេញ (យក \(\cos 30^\circ \approx 0.866\))។
ខ. ប្រសិនបើគាត់បន្ទាបខ្សែពួរឱ្យស្របនឹងដី (\(\theta = 0^\circ\)) ដោយបញ្ចេញកម្លាំង 200 N ដដែល តើគាត់នឹងទទួលបានកម្មន្តប៉ុន្មាន?
គ. ប្រៀបធៀបលទ្ធផលទាំងពីរ និងពន្យល់ពីសារៈសំខាន់នៃមុំទាញក្នុងជីវភាពរស់នៅ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា W_1: W_1 = F * d * \cos 30° = 200 * 50 * 0.866 = 8660 J = 8.66 kJ (1.5 ពិន្ទុ)
គណនា W_2: W_2 = F * d * \cos 0° = 200 * 50 * 1 = 10000 J = 10 kJ (1.5 ពិន្ទុ)
ប្រៀបធៀប: W_2 ធំជាង W_1 ចំនួន 1340 J (15.5%) (1 ពិន្ទុ)
ពន្យល់: ការទាញស្របនឹងទិសដៅបំលាស់ទីផ្តល់ប្រសិទ្ធភាពកម្មន្តខ្ពស់បំផុត ដោយមិនខ្ជះខ្ជាយកម្លាំងទៅលើទិសឈរ (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12150, 'PISA ហ្គេមបាញ់ធ្នូ និងវ៉ិចទ័រល្បឿន: ព្រួញធ្នូមួយត្រូវបានបាញ់ចេញពីធ្នូដោយល្បឿនដើម \(v_0 = 40\text{ m/s}\) បង្កើតបានមុំ \(60^\circ\) ធៀបនឹងដីផ្ដេក។
ក. គណនាសមាសភាគល្បឿនផ្ដេក \(v_x = v_0 \cos 60^\circ\) និងសមាសភាគល្បឿនឈរ \(v_y = v_0 \sin 60^\circ\)។
ខ. សរសេរវ៉ិចទ័រល្បឿនដើម \(\vec{v}_0\) ជាអនុគមន៍នៃវ៉ិចទ័រឯកតា \(\vec{i}\) និង \(\vec{j}\)។
គ. បើមិនគិតកម្លាំងកកិតខ្យល់ សមាសភាគល្បឿនផ្ដេក \(v_x\) ថេររហូត។ គណនាចម្ងាយផ្ដេកដែលព្រួញហោះបានក្រោយពេល 3 វិនាទី។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា v_x = 40 * \cos 60° = 40 * 0.5 = 20 m/s (1.5 ពិន្ទុ)
គណនា v_y = 40 * \sin 60° = 40 * (\sqrt{3}/2) = 20\sqrt{3} ≈ 34.64 m/s (1.5 ពិន្ទុ)
សរសេរវ៉ិចទ័រ: \vec{v}_0 = 20\vec{i} + 20\sqrt{3}\vec{j} (m/s) (1 ពិន្ទុ)
គណនាចម្ងាយផ្ដេក: x = v_x * t = 20 * 3 = 60 m (1 ពិន្ទុ)', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'pisa', 0, '10', 'វ៉ិចទ័រនិងប្រមាណវិធីលើវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12201, 'បើគេយក O ជាគល់នៃប្លង់ តើវ៉ិចទ័រទីតាំងនៃចំណុច P កំណត់ដោយអ្វី?', NULL, '["\\(\\vec{p} = 0\\)", "\\(P = O\\)", "\\(\\vec{OP} = \\vec{p}\\)", "\\(\\vec{PO} = \\vec{p}\\)"]', 2, NULL, 1, 'mcq', 'វ៉ិចទ័រទីតាំងនៃចំណុច P ដែលមាន O ជាគល់ គឺវ៉ិចទ័រ OP = p កំណត់សរសេរ P(p)។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
