INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12202, 'ពិនិត្យរូបភាពត្រីកោណ ABC ខាងក្រោម។ តើវ៉ិចទ័រទីតាំងនៃទីប្រជុំទម្ងន់ G កំណត់ដោយរូបមន្តណា?', 'g10-895bc78294.svg', '["\\(\\vec{g} = \\dfrac{2\\vec{a} + \\vec{b} + \\vec{c}}{4}\\)", "\\(\\vec{g} = \\dfrac{\\vec{a} + \\vec{b} + \\vec{c}}{3}\\)", "\\(\\vec{g} = \\dfrac{\\vec{a} + \\vec{b} + \\vec{c}}{2}\\)", "\\(\\vec{g} = \\vec{a} + \\vec{b} + \\vec{c}\\)"]', 1, NULL, 1, 'mcq', 'ទីប្រជុំទម្ងន់ G នៃត្រីកោណ ABC មានវ៉ិចទ័រទីតាំង g = (a + b + c) / 3។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
