INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12203, 'ពិនិត្យរូបភាពខាងក្រោម។ សមីការវ៉ិចទ័រនៃរង្វង់ដែលមានផ្ចិត \(C(\vec{c})\) និងកាំ \(R\) គឺ៖', 'g10-c95ea550ab.svg', '["\\(|\\vec{r}| = R\\)", "\\(|\\vec{r} + \\vec{c}| = R\\)", "\\(|\\vec{r} - \\vec{c}| = R\\)", "\\(\\vec{r} \\cdot \\vec{c} = R^2\\)"]', 2, NULL, 1, 'mcq', 'ចម្ងាយពីផ្ចិត C(c) ទៅចំណុច P(r) លើរង្វង់ស្មើកាំ R នាំឱ្យ |r - c| = R (ឬ (r - c)^2 = R^2)។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
