INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12204, 'ពិនិត្យរូបខាងក្រោម។ កម្លាំងពីរ \(\vec{F}_1\) និង \(\vec{F}_2\) មានចំណុចចាប់រួមគ្នា។ តើកម្លាំងផ្គួប \(\vec{F}\) ស្មើនឹងអ្វី?', 'g10-6dcea94072.svg', '["\\(\\vec{F} = \\vec{F}_1 \\cdot \\vec{F}_2\\)", "\\(\\vec{F} = \\vec{F}_1 - \\vec{F}_2\\)", "\\(\\vec{F} = \\vec{F}_1 + \\vec{F}_2\\)", "\\(F = F_1 \\times F_2\\)"]', 2, NULL, 1, 'mcq', 'កម្លាំងផ្គួបនៃកម្លាំងពីរមានចំណុចចាប់រួមគ្នាគឺផលបូកវ៉ិចទ័រ F = F_1 + F_2 តាមវិធានប្រលេឡូក្រាម។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12205, 'បើ \(A(\vec{a})\) និង \(B(\vec{b})\) ជាចំណុចពីរក្នុងប្លង់ តើ \(\vec{AB}\) ស្មើនឹងអ្វី?', NULL, '["\\(\\vec{a} - \\vec{b}\\)", "\\(\\vec{a} + \\vec{b}\\)", "\\(\\vec{b} - \\vec{a}\\)", "\\(\\vec{a} \\cdot \\vec{b}\\)"]', 2, NULL, 1, 'mcq', 'AB = OB - OA = b - a (វ៉ិចទ័រទីតាំងចុងដកវ៉ិចទ័រទីតាំងគល់)។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12206, 'បើ G ជាទីប្រជុំទម្ងន់នៃត្រីកោណ ABC តើផលបូក \(\vec{GA} + \vec{GB} + \vec{GC}\) ស្មើនឹងអ្វី?', NULL, '["\\(\\vec{AB} + \\vec{BC}\\)", "\\(1\\)", "\\(\\vec{0}\\)", "\\(3\\vec{OG}\\)"]', 2, NULL, 1, 'mcq', 'លក្ខណៈគ្រឹះនៃទីប្រជុំទម្ងន់ត្រីកោណគឺ GA + GB + GC = 0។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12207, 'បន្ទាត់ L កាត់តាមចំណុច \(A(\vec{a})\) ហើយស្របនឹងវ៉ិចទ័រប្រាប់ទិស \(\vec{u}\)។ សមីការវ៉ិចទ័រនៃបន្ទាត់ L គឺ៖', NULL, '["\\(\\vec{r} = \\vec{a} + t\\vec{u}\\quad (t \\in \\mathbb{R})\\)", "\\(\\vec{r} = \\vec{a} - t\\vec{u}^2\\)", "\\(\\vec{r} = t\\vec{a} + \\vec{u}\\)", "\\(\\vec{r} = \\vec{a} \\cdot \\vec{u}\\)"]', 0, NULL, 1, 'mcq', 'សមីការវ៉ិចទ័រនៃបន្ទាត់កាត់តាម A(a) ស្របនឹង u គឺ r = a + t*u។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12208, 'តើរូបមន្តគណនាកម្មន្ត \(W\) នៃកម្លាំងថេរ \(\vec{F}\) លើបំលាស់ទី \(\vec{d}\) គឺជាអ្វី?', NULL, '["\\(W = |\\vec{F}| + |\\vec{d}|\\)", "\\(W = |\\vec{F}||\\vec{d}|\\sin\\theta\\)", "\\(W = \\dfrac{|\\vec{F}|}{|\\vec{d}|}\\)", "\\(W = \\vec{F} \\cdot \\vec{d} = |\\vec{F}||\\vec{d}|\\cos\\theta\\)"]', 3, NULL, 1, 'mcq', 'កម្មន្តនៃកម្លាំងគឺផលគុណស្កាលែរវាងកម្លាំងនិងបំលាស់ទី W = F . d = |F||d|cos theta។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12209, 'បើ M ជាចំណុចកណ្តាលនៃអង្កត់ AB ដែល \(A(\vec{a})\) និង \(B(\vec{b})\) នោះវ៉ិចទ័រទីតាំង \(\vec{m}\) នៃ M គឺ៖', NULL, '["\\(\\vec{m} = \\dfrac{\\vec{a} + \\vec{b}}{2}\\)", "\\(\\vec{m} = \\vec{a} + \\vec{b}\\)", "\\(\\vec{m} = \\dfrac{\\vec{b} - \\vec{a}}{2}\\)", "\\(\\vec{m} = 2(\\vec{a} + \\vec{b})\\)"]', 0, NULL, 1, 'mcq', 'វ៉ិចទ័រទីតាំងចំណុចកណ្តាល M គឺ m = (a + b) / 2។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12210, 'រកវ៉ិចទ័រណរម៉ាល់ (កែង) \(\vec{n}\) នៃបន្ទាត់ \(3x - 4y + 1 = 0\)៖', NULL, '["\\(\\vec{n} = (3,\\, -4)\\)", "\\(\\vec{n} = (-3,\\, -4)\\)", "\\(\\vec{n} = (3,\\, 4)\\)", "\\(\\vec{n} = (4,\\, 3)\\)"]', 0, NULL, 1, 'mcq', 'បន្ទាត់ ax + by + c = 0 មានវ៉ិចទ័រណរម៉ាល់ n = (a, b) = (3, -4)។', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12211, 'គេមាន \(A(2,\, 5)\) និង \(B(8,\, 11)\)។ រកកូអរដោនេនៃចំណុចកណ្តាល M នៃអង្កត់ AB៖', NULL, '["\\(M(4,\\, 3)\\)", "\\(M(5,\\, 8)\\)", "\\(M(10,\\, 16)\\)", "\\(M(6,\\, 6)\\)"]', 1, NULL, 2, 'mcq', 'x_M = (2 + 8)/2 = 5 និង y_M = (5 + 11)/2 = 8 នាំឱ្យ M(5, 8)។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12212, 'ត្រីកោណ ABC មានកំពូល \(A(1,\, 2),\, B(3,\, 8),\, C(5,\, 2)\)។ រកកូអរដោនេនៃទីប្រជុំទម្ងន់ G នៃត្រីកោណ ABC៖', NULL, '["\\(G(3,\\, 6)\\)", "\\(G(9,\\, 12)\\)", "\\(G(3,\\, 4)\\)", "\\(G(4,\\, 4)\\)"]', 2, NULL, 2, 'mcq', 'x_G = (1 + 3 + 5)/3 = 9/3 = 3 និង y_G = (2 + 8 + 2)/3 = 12/3 = 4 នាំឱ្យ G(3, 4)។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12213, 'បន្ទាត់ L កាត់តាមចំណុច \(A(2,\, -1)\) ហើយមានវ៉ិចទ័រប្រាប់ទិស \(\vec{u} = (3,\, 5)\)។ សមីការប៉ារ៉ាម៉ែត្រនៃបន្ទាត់ L គឺ៖', NULL, '["\\(\\begin{cases} x = 2 + 5t \\\\ y = -1 + 3t \\end{cases}\\)", "\\(\\begin{cases} x = 2 - 3t \\\\ y = -1 - 5t \\end{cases}\\)", "\\(\\begin{cases} x = 3 + 2t \\\\ y = 5 - t \\end{cases}\\)", "\\(\\begin{cases} x = 2 + 3t \\\\ y = -1 + 5t \\end{cases}\\)"]', 3, NULL, 2, 'mcq', 'សមីការប៉ារ៉ាម៉ែត្រ: x = x_0 + at = 2 + 3t និង y = y_0 + bt = -1 + 5t។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12214, 'កម្លាំងពីរស្មើគ្នា \(F_1 = F_2 = 10\text{ N}\) បង្កើតបានមុំ \(60^\circ\) រវាងគ្នា។ គណនាម៉ូឌុលនៃកម្លាំងផ្គួប \(F\)៖', NULL, '["\\(10\\sqrt{3}\\text{ N}\\approx 17.32\\text{ N}\\)", "\\(15\\text{ N}\\)", "\\(20\\text{ N}\\)", "\\(10\\text{ N}\\)"]', 0, NULL, 2, 'mcq', 'F = sqrt(10^2 + 10^2 + 2(10)(10)cos 60°) = sqrt(100 + 100 + 100) = sqrt(300) = 10*sqrt(3) N។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12215, 'ចំណុច C ចែកអង្កត់ AB ខាងក្នុងតាមផលធៀប 2:1។ រកកន្សោម \(\vec{c}\) ជាអនុគមន៍នៃ \(\vec{a}\) និង \(\vec{b}\)៖', NULL, '["\\(\\vec{c} = \\dfrac{\\vec{a} + 2\\vec{b}}{3}\\)", "\\(\\vec{c} = \\dfrac{\\vec{a} + \\vec{b}}{3}\\)", "\\(\\vec{c} = \\dfrac{2\\vec{a} + \\vec{b}}{3}\\)", "\\(\\vec{c} = 2\\vec{b} - \\vec{a}\\)"]', 0, NULL, 2, 'mcq', 'c = (2b + 1a) / (2 + 1) = (a + 2b) / 3។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12216, 'គេមានត្រីកោណ ABC ដែលមានកំពូល \(A(2,\, 1),\, B(4,\, 7)\) និងទីប្រជុំទម្ងន់ \(G(3,\, 5)\)។ រកកូអរដោនេនៃកំពូល C៖', NULL, '["\\(C(6,\\, 8)\\)", "\\(C(1,\\, 3)\\)", "\\(C(3,\\, 7)\\)", "\\(C(3,\\, 5)\\)"]', 2, NULL, 2, 'mcq', 'x_C = 3(3) - (2 + 4) = 9 - 6 = 3; y_C = 3(5) - (1 + 7) = 15 - 8 = 7 នាំឱ្យ C(3, 7)។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12217, 'បន្ទាត់មួយកាត់តាមចំណុច \(A(1,\, 3)\) និងកែងនឹងវ៉ិចទ័រណរម៉ាល់ \(\vec{n} = (2,\, -1)\)។ សមីការទូទៅនៃបន្ទាត់នោះគឺ៖', NULL, '["\\(2x - y - 1 = 0\\)", "\\(x + 2y - 7 = 0\\)", "\\(2x - y + 1 = 0\\)", "\\(2x + y - 5 = 0\\)"]', 2, NULL, 2, 'mcq', '2(x - 1) - 1(y - 3) = 0 <=> 2x - 2 - y + 3 = 0 <=> 2x - y + 1 = 0។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12218, 'កម្លាំង \(\vec{F} = (8,\, 6)\) N បានធ្វើឱ្យអង្គធាតុមួយបំលាស់ទីបាន \(\vec{d} = (5,\, 2)\) m។ គណនាកម្មន្ត W ដែលកម្លាំងបានបំពេញ៖', NULL, '["\\(52\\text{ J}\\)", "\\(40\\text{ J}\\)", "\\(26\\text{ J}\\)", "\\(64\\text{ J}\\)"]', 0, NULL, 2, 'mcq', 'W = F . d = (8)(5) + (6)(2) = 40 + 12 = 52 J។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12219, 'គេមានចំណុច \(A(1,\, 2)\) និង \(B(7,\, 5)\)។ ចំណុច C ចែក AB ខាងក្នុងតាមផលធៀប 2:1 (AC : CB = 2 : 1)។ រកកូអរដោនេនៃ C៖', NULL, '["\\(C(3,\\, 3)\\)", "\\(C(4,\\, 3.5)\\)", "\\(C(5,\\, 4)\\)", "\\(C(6,\\, 4.5)\\)"]', 2, NULL, 2, 'mcq', 'x_C = (1 + 2(7))/3 = 15/3 = 5 និង y_C = (2 + 2(5))/3 = 12/3 = 4 នាំឱ្យ C(5, 4)។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12220, 'រង្វង់មួយមានផ្ចិត \(C(3,\, -2)\) និងកាំ \(R = 4\)។ សមីការស្តង់ដានៃរង្វង់នេះគឺ៖', NULL, '["\\((x + 3)^2 + (y - 2)^2 = 16\\)", "\\((x - 3)^2 + (y + 2)^2 = 4\\)", "\\((x - 3)^2 + (y + 2)^2 = 16\\)", "\\((x - 3)^2 + (y - 2)^2 = 16\\)"]', 2, NULL, 2, 'mcq', 'តាមរូបមន្ត (x - a)^2 + (y - b)^2 = R^2: (x - 3)^2 + (y + 2)^2 = 16។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12221, 'កម្លាំង \(F = 40\text{ N}\) ទាញប្រអប់មួយបានចម្ងាយ \(d = 10\text{ m}\) ដោយខ្សែពួរបង្កើតមុំ \(60^\circ\) ធៀបនឹងប្លង់ដេក។ គណនាកម្មន្ត W៖', NULL, '["\\(200\\text{ J}\\)", "\\(200\\sqrt{3}\\text{ J}\\)", "\\(100\\text{ J}\\)", "\\(400\\text{ J}\\)"]', 0, NULL, 2, 'mcq', 'W = F * d * cos 60° = 40 * 10 * (1/2) = 200 J។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12222, 'ចំណុច D ចែកអង្កត់ AB ខាងក្រៅតាមផលធៀប 3:1។ រកកន្សោម \(\vec{d}\) ជាអនុគមន៍នៃ \(\vec{a}\) និង \(\vec{b}\)៖', NULL, '["\\(\\vec{d} = \\dfrac{\\vec{b} - 3\\vec{a}}{2}\\)", "\\(\\vec{d} = \\dfrac{3\\vec{b} + \\vec{a}}{4}\\)", "\\(\\vec{d} = 3\\vec{b} - \\vec{a}\\)", "\\(\\vec{d} = \\dfrac{3\\vec{b} - \\vec{a}}{2}\\)"]', 3, NULL, 2, 'mcq', 'd = (3b - 1a) / (3 - 1) = (3b - a) / 2។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12223, 'សមីការប៉ារ៉ាម៉ែត្រនៃបន្ទាត់មួយគឺ \(\begin{cases} x = 3 - 2t \\ y = 1 + 4t \end{cases}\)។ រកវ៉ិចទ័រប្រាប់ទិស \(\vec{u}\) នៃបន្ទាត់នោះ៖', NULL, '["\\(\\vec{u} = (-2,\\, 4)\\)", "\\(\\vec{u} = (4,\\, -2)\\)", "\\(\\vec{u} = (3,\\, 1)\\)", "\\(\\vec{u} = (2,\\, 4)\\)"]', 0, NULL, 2, 'mcq', 'មេគុណមុខ t គឺ a = -2 និង b = 4 នាំឱ្យវ៉ិចទ័រប្រាប់ទិស u = (-2, 4) (ឬកូលីនេអ៊ែរនឹង (-1, 2))។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12224, 'កម្លាំងបី \(\vec{F}_1 = (3,\, 4),\, \vec{F}_2 = (-1,\, 2),\, \vec{F}_3\) ធ្វើឱ្យអង្គធាតុមួយមានលំនឹង (\(\sum\vec{F} = \vec{0}\))។ រកកូអរដោនេនៃ \(\vec{F}_3\)៖', NULL, '["\\(\\vec{F}_3 = (2,\\, 6)\\)", "\\(\\vec{F}_3 = (4,\\, 2)\\)", "\\(\\vec{F}_3 = (-2,\\, -6)\\)", "\\(\\vec{F}_3 = (-2,\\, 6)\\)"]', 2, NULL, 2, 'mcq', 'F_3 = -(F_1 + F_2) = -((3 - 1, 4 + 2)) = -(2, 6) = (-2, -6) N។', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12225, 'ក្នុងត្រីកោណ ABC ចំណុច D ចែក BC តាមផលធៀប \(BD : DC = 1 : 2\)។ កន្សោម \(\vec{AD}\) ជាអនុគមន៍នៃ \(\vec{AB}\) និង \(\vec{AC}\) គឺ៖', NULL, '["\\(\\vec{AD} = \\dfrac{2}{3}\\vec{AB} + \\dfrac{1}{3}\\vec{AC}\\)", "\\(\\vec{AD} = \\dfrac{1}{3}\\vec{AB} + \\dfrac{2}{3}\\vec{AC}\\)", "\\(\\vec{AD} = \\dfrac{1}{2}(\\vec{AB} + \\vec{AC})\\)", "\\(\\vec{AD} = 2\\vec{AB} - \\vec{AC}\\)"]', 0, NULL, 3, 'mcq', 'D ចែក BC តាមផលធៀប 1:2 នាំឱ្យ AD = (2*AB + 1*AC) / (1 + 2) = (2/3)AB + (1/3)AC។', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12226, 'បើ G ជាទីប្រជុំទម្ងន់ត្រីកោណ ABC និង O ជាចំណុចណាមួយក្នុងប្លង់ បង្ហាញថា \(\vec{OA} + \vec{OB} + \vec{OC} = 3\vec{OG}\)។ បើ \(\vec{OA} + \vec{OB} + \vec{OC} = \vec{0}\) តើ O ជាចំណុចណា?', NULL, '["O ជាទីប្រជុំទម្ងន់ G នៃត្រីកោណ ABC", "O ជាអរតូសង់នៃត្រីកោណ", "O ជាចំណុចកណ្តាលនៃ BC", "O ជាផ្ចិតរង្វង់ចារឹកក្រៅត្រីកោណ"]', 0, NULL, 3, 'mcq', 'OA + OB + OC = 3OG។ បើ OA + OB + OC = 0 នាំឱ្យ 3OG = 0 <=> OG = 0 <=> O ត្រួតស៊ីគ្នានឹង G។', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12227, 'បន្ទាត់មួយមានសមីការវ៉ិចទ័រ \(\vec{r} = (1,\, 2) + t(3,\, -1)\)។ សរសេរសមីការទូទៅនៃបន្ទាត់នោះតាមទម្រង់ \(ax + by + c = 0\)៖', NULL, '["\\(x - 3y + 5 = 0\\)", "\\(x + 3y - 7 = 0\\)", "\\(3x + y - 5 = 0\\)", "\\(3x - y - 1 = 0\\)"]', 1, NULL, 3, 'mcq', 'x = 1 + 3t => t = (x - 1)/3; y = 2 - t => t = 2 - y។ ស្មើគ្នា: (x - 1)/3 = 2 - y <=> x - 1 = 6 - 3y <=> x + 3y - 7 = 0។', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12228, 'កម្លាំងពីរមានម៉ូឌុល \(F_1 = 6\text{ N}\) និង \(F_2 = 10\text{ N}\)។ តើកម្លាំងផ្គួប \(F\) អាចមានតម្លៃក្នុងចន្លោះណា?', NULL, '["\\([8\\text{ N},\\, 12\\text{ N}]\\)", "\\([0\\text{ N},\\, 16\\text{ N}]\\)", "\\([6\\text{ N},\\, 10\\text{ N}]\\)", "\\([4\\text{ N},\\, 16\\text{ N}]\\)"]', 3, NULL, 3, 'mcq', 'F_min = |F_1 - F_2| = |6 - 10| = 4 N (ទិសដៅផ្ទុយ) និង F_max = F_1 + F_2 = 16 N (ទិសដៅដូចគ្នា) នាំឱ្យ F in [4 N, 16 N]។', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12229, 'គេមានចំណុច \(A(\vec{a}),\, B(\vec{b}),\, C(\vec{c})\)។ លក្ខខណ្ឌចាំបាច់និងគ្រប់គ្រាន់ដើម្បីឱ្យ A, B, C រត់ត្រង់ជួរគ្នាគឺមានចំនួនពិត \(\alpha,\, \beta,\, \gamma\) មិនសូន្យព្រមគ្នាដែល ៖', NULL, '["\\(\\vec{a} + \\vec{b} + \\vec{c} = \\vec{0}\\)", "\\(\\alpha\\vec{a} + \\beta\\vec{b} + \\gamma\\vec{c} = \\vec{0}\\text{ និង }\\alpha + \\beta + \\gamma = 1\\)", "\\(\\alpha\\vec{a} + \\beta\\vec{b} + \\gamma\\vec{c} = \\vec{0}\\text{ និង }\\alpha + \\beta + \\gamma = 0\\)", "\\(\\vec{a} \\cdot \\vec{b} \\cdot \\vec{c} = 0\\)"]', 2, NULL, 3, 'mcq', 'ទ្រឹស្តីបទបារីសង់ត្រង់ជួរ: alpha*a + beta*b + gamma*c = 0 ជាមួយ alpha + beta + gamma = 0។', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12230, 'ត្រីកោណ ABC មានទីប្រជុំទម្ងន់ G។ ចំណុច M ជាចំណុចកណ្តាលនៃ AG។ បង្ហាញថា \(4\vec{MA} + \vec{MB} + \vec{MC} = \vec{0}\) ឬទំនាក់ទំនង \(\vec{AM}\) ស្មើនឹង៖', NULL, '["\\(\\vec{AM} = \\vec{AB} + \\vec{AC}\\)", "\\(\\vec{AM} = \\dfrac{1}{3}(\\vec{AB} + \\vec{AC})\\)", "\\(\\vec{AM} = \\dfrac{1}{6}(\\vec{AB} + \\vec{AC})\\)", "\\(\\vec{AM} = \\dfrac{1}{4}(\\vec{AB} + \\vec{AC})\\)"]', 2, NULL, 3, 'mcq', 'AG = (2/3)AL = (2/3)(1/2)(AB + AC) = (1/3)(AB + AC)។ M ជាចំណុចកណ្តាល AG នាំឱ្យ AM = (1/2)AG = (1/6)(AB + AC)។', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12231, 'រកសមីការបន្ទាត់ប៉ះទៅនឹងរង្វង់ \(x^2 + y^2 = 25\) ត្រង់ចំណុច \(P_0(3,\, 4)\) ដោយប្រើផលគុណស្កាលែនៃវ៉ិចទ័រ៖', NULL, '["\\(3x + 4y - 25 = 0\\)", "\\(3x - 4y + 7 = 0\\)", "\\(4x - 3y = 0\\)", "\\(3x + 4y + 25 = 0\\)"]', 0, NULL, 3, 'mcq', 'វ៉ិចទ័រកាំ OP_0 = (3, 4) ជាវ៉ិចទ័រណរម៉ាល់នៃបន្ទាត់ប៉ះត្រង់ P_0 នាំឱ្យ 3(x - 3) + 4(y - 4) = 0 <=> 3x + 4y - 25 = 0។', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12232, 'PISA អាកាសចរណ៍: យន្តហោះដឹកអ្នកដំណើរមួយត្រូវហោះហើរឆ្ពោះទៅទិសខាងកើតត្រង់ពីភ្នំពេញទៅកាន់ទីក្រុងហូជីមិញ។ ប្រសិនបើមានខ្យល់ព្យុះបក់ខ្លាំងពីទិសខាងត្បូងទៅជើង តើអ្នកបើកបរត្រូវតម្រង់ក្បាលយន្តហោះឆ្ពោះទៅទិសណាដើម្បីកុំឱ្យយន្តហោះរសាត់ខុសផ្លូវ?', NULL, '["តម្រង់ក្បាលយន្តហោះទៅទិសខាងកើតត្រង់", "តម្រង់ក្បាលយន្តហោះបញ្ឆិតទៅទិសអាគ្នេយ៍ (East-Southeast)", "តម្រង់ក្បាលយន្តហោះទៅទិសខាងជើង", "តម្រង់ក្បាលយន្តហោះទៅទិសឦសាន"]', 1, NULL, 3, 'mcq', 'ដើម្បីបន្សាបសមាសភាគល្បឿនខ្យល់ដែលរុញទៅជើង យន្តហោះត្រូវមានសមាសភាគល្បឿនចង្អុលទៅត្បូង ដូច្នេះត្រូវតម្រង់ទៅទិសអាគ្នេយ៍។', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12233, 'PISA ស្ទូចទំនិញកំពង់ផែ: ស្ទូចមួយលើកកុងតឺន័រទម្ងន់ 20000 N ឡើងលើដោយល្បឿនថេរតាមទិសឈរបានកម្ពស់ 15 m។ គណនាកម្មន្តដែលស្ទូចបានបំពេញ៖', NULL, '["\\(300\\,000\\text{ J} = 300\\text{ kJ}\\)", "\\(20\\,015\\text{ J}\\)", "\\(1\\,333.3\\text{ J}\\)", "\\(0\\text{ J}\\)"]', 0, NULL, 3, 'mcq', 'W = F * d = 20000 * 15 = 300000 J = 300 kJ (theta = 0° ព្រោះកម្លាំងលើកស្របទិសដៅបំលាស់ទី)។', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12234, 'PISA អាជីវកម្មអូសទូក: គេប្រើសេះពីរដើម្បីអូសទូកមួយតាមព្រែកជីក។ សេះទាំងពីរបញ្ចេញកម្លាំងស្មើគ្នា \(F_1 = F_2 = 800\text{ N}\) នៅសងខាងច្រាំងព្រែក ដោយខ្សែពួរទាំងពីរបង្កើតបានមុំ \(60^\circ\) រវាងគ្នា។ គណនាកម្លាំងផ្គួបដែលទាញទូកទៅមុខតាមបណ្តោយព្រែក៖', NULL, '["\\(800\\text{ N}\\)", "\\(1\\,200\\text{ N}\\)", "\\(1\\,600\\text{ N}\\)", "\\(800\\sqrt{3}\\text{ N}\\approx 1\\,385.6\\text{ N}\\)"]', 3, NULL, 3, 'mcq', 'F_res = 2 * F * cos(30°) = 2 * 800 * (sqrt(3)/2) = 800*sqrt(3) ≈ 1385.64 N។', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12235, 'PISA កីឡាជិះទូកក្តោង: ទូកក្តោងមួយត្រូវបានកម្លាំងខ្យល់ \(\vec{F} = (120,\, 50)\) N រុញច្រានឱ្យបំលាស់ទីបាន \(\vec{d} = (200,\, 0)\) m តាមបណ្តោយទិសដេក។ គណនាកម្មន្តដែលខ្យល់បានបង្កើតឡើង៖', NULL, '["\\(10\\,000\\text{ J}\\)", "\\(34\\,000\\text{ J}\\)", "\\(24\\,000\\text{ J} = 24\\text{ kJ}\\)", "\\(26\\,000\\text{ J}\\)"]', 2, NULL, 3, 'mcq', 'W = F . d = (120)(200) + (50)(0) = 24000 J = 24 kJ។', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12236, 'PISA រចនាសម្ព័ន្ធស្ពាន: ខ្សែខ្សែកាបព្យួរស្ពានមួយត្រូវបានរចនាឱ្យទប់កម្លាំងផ្គួបនៃទម្ងន់ស្ពាន។ ប្រសិនបើកម្លាំងទម្ងន់ស្ពានទាញចុះក្រោម 50000 N ហើយខ្សែខ្សែកាបពីរសងខាងបញ្ចេញកម្លាំងតំណឹងស្មើគ្នា T មុំ 45 ដឺក្រេធៀបនឹងទិសឈរ តើ T ត្រូវស្មើនឹងប៉ុន្មានដើម្បីឱ្យស្ពានមានលំនឹង?', NULL, '["\\(25\\,000\\text{ N}\\)", "\\(25\\,000\\sqrt{2}\\text{ N}\\approx 35\\,355\\text{ N}\\)", "\\(50\\,000\\text{ N}\\)", "\\(35\\,000\\text{ N}\\)"]', 1, NULL, 3, 'mcq', 'លំនឹងទិសឈរ: 2T cos 45° = 50000 => 2T(sqrt(2)/2) = 50000 => T*sqrt(2) = 50000 => T = 25000*sqrt(2) ≈ 35355.3 N។', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 1, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12237, 'ក្នុងប្លង់កូអរដោនេ គេមានចំណុច \(A(2,\, 3)\) និង \(B(6,\, 7)\)។
ក. សរសេរវ៉ិចទ័រទីតាំង \(\vec{a}\) និង \(\vec{b}\) នៃចំណុច A និង B។
ខ. គណនាកូអរដោនេនៃចំណុចកណ្តាល M នៃអង្កត់ AB ដោយប្រើរូបមន្តវ៉ិចទ័រទីតាំង។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរវ៉ិចទ័រទីតាំង: \vec{a} = \vec{OA} = (2, 3) និង \vec{b} = \vec{OB} = (6, 7) (1.5 ពិន្ទុ)
សរសេររូបមន្តចំណុចកណ្តាល: \vec{m} = \dfrac{\vec{a} + \vec{b}}{2} (1.5 ពិន្ទុ)
ជំនួសតម្លៃគណនា: \vec{m} = \dfrac{(2 + 6, 3 + 7)}{2} = \dfrac{(8, 10)}{2} = (4, 5) (1 ពិន្ទុ)
សន្និដ្ឋានកូអរដោនេ: M(4, 5) (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'easy', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12238, 'គេមានចំណុច \(A(1,\, 2)\) និង \(B(7,\, 8)\)។ ចំណុច C ចែកអង្កត់ AB ខាងក្នុងតាមផលធៀប \(2 : 1\) (គឺ \(AC : CB = 2 : 1\))។
ក. សរសេររូបមន្តវ៉ិចទ័រទីតាំង \(\vec{c}\) ជាអនុគមន៍នៃ \(\vec{a}\) និង \(\vec{b}\)។
ខ. គណនាកូអរដោនេនៃចំណុច C។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តចំណុចចែកក្នុង: \vec{c} = \dfrac{m\vec{b} + n\vec{a}}{m + n} (1.5 ពិន្ទុ)
ជំនួស m = 2, n = 1: \vec{c} = \dfrac{2\vec{b} + \vec{a}}{3} (1 ពិន្ទុ)
គណនា x_C: x_C = (2(7) + 1)/3 = (14 + 1)/3 = 5 (1.5 ពិន្ទុ)
គណនា y_C: y_C = (2(8) + 2)/3 = (16 + 2)/3 = 6 នាំឱ្យ C(5, 6) (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12239, 'គេមានត្រីកោណ ABC ដែលមានកំពូល \(A(2,\, 4),\, B(6,\, 2),\, C(4,\, 9)\) ក្នុងប្លង់កូអរដោនេ។
ក. រកកូអរដោនេនៃទីប្រជុំទម្ងន់ G នៃត្រីកោណ ABC។
ខ. គណនាផលបូកវ៉ិចទ័រ \(\vec{GA} + \vec{GB} + \vec{GC}\) ដើម្បីផ្ទៀងផ្ទាត់លក្ខណៈនៃទីប្រជុំទម្ងន់។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តទីប្រជុំទម្ងន់: \vec{g} = (\vec{a} + \vec{b} + \vec{c})/3 (1 ពិន្ទុ)
គណនាកូអរដោនេ G: x_G = (2 + 6 + 4)/3 = 4, y_G = (4 + 2 + 9)/3 = 5 នាំឱ្យ G(4, 5) (1.5 ពិន្ទុ)
គណនាកូអរដោនេ: \vec{GA} = (-2, -1), \vec{GB} = (2, -3), \vec{GC} = (0, 4) (1.5 ពិន្ទុ)
បូកផ្ទៀងផ្ទាត់: (-2 + 2 + 0, -1 - 3 + 4) = (0, 0) = \vec{0} ត្រឹមត្រូវ (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12240, 'បន្ទាត់ L មួយកាត់តាមចំណុច \(A(3,\, -2)\) ហើយកែងនឹងវ៉ិចទ័រណរម៉ាល់ \(\vec{n} = (4,\, 5)\)។
ក. សរសេរសមីការវ៉ិចទ័រនៃបន្ទាត់ L តាមរូបមន្ត \(\vec{n} \cdot (\vec{r} - \vec{a}) = 0\)។
ខ. បំប្លែងទៅជាសមីការទូទៅ \(ax + by + c = 0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរកន្សោមវ៉ិចទ័រ: \vec{r} - \vec{a} = (x - 3, y - (-2)) = (x - 3, y + 2) (1.5 ពិន្ទុ)
សរសេរផលគុណស្កាលែ: (4, 5) \cdot (x - 3, y + 2) = 0 (1.5 ពិន្ទុ)
ពន្លាតសមីការ: 4(x - 3) + 5(y + 2) = 0 <=> 4x - 12 + 5y + 10 = 0 (1 ពិន្ទុ)
បង្រួមសមីការទូទៅ: 4x + 5y - 2 = 0 (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12241, 'កម្លាំងពីរ \(\vec{F}_1\) និង \(\vec{F}_2\) មានទំហំ \(F_1 = 30\text{ N}\) និង \(F_2 = 50\text{ N}\) មានចំណុចចាប់រួមគ្នា និងបង្កើតបានមុំ \(\theta = 60^\circ\)។
ក. សរសេររូបមន្តគណនាម៉ូឌុលនៃកម្លាំងផ្គួប F។
ខ. គណនាម៉ូឌុលកម្លាំងផ្គួប F (យក \(\sqrt{4\,900} = 70\))។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្ត: F = \sqrt{F_1^2 + F_2^2 + 2F_1 F_2 \cos\theta} (1.5 ពិន្ទុ)
ជំនួសតម្លៃ: F^2 = 30^2 + 50^2 + 2(30)(50)\cos 60° (1.5 ពិន្ទុ)
គណនាតម្លៃលេខ: F^2 = 900 + 2500 + 3000(0.5) = 3400 + 1500 = 4900 (1 ពិន្ទុ)
ទាញរកម៉ូឌុល: F = \sqrt{4900} = 70 N (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'medium', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12242, 'គេមានចំណុច \(A(1,\, 2)\) និង \(B(4,\, 5)\)។ ចំណុច D ចែកអង្កត់ AB ខាងក្រៅតាមផលធៀប \(2 : 1\) (គឺ \(DA : DB = 2 : 1\))។
ក. សរសេររូបមន្តវ៉ិចទ័រទីតាំង \(\vec{d}\) នៃចំណុចចែកក្រៅ។
ខ. គណនាកូអរដោនេនៃចំណុច D ព្រមទាំងផ្ទៀងផ្ទាត់ថា B ជាចំណុចកណ្តាលនៃ AD។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តចំណុចចែកក្រៅ: \vec{d} = \dfrac{m\vec{b} - n\vec{a}}{m - n} (1.5 ពិន្ទុ)
ជំនួស m = 2, n = 1: \vec{d} = \dfrac{2\vec{b} - \vec{a}}{2 - 1} = 2\vec{b} - \vec{a} (1.5 ពិន្ទុ)
គណនាកូអរដោនេ D: x_D = 2(4) - 1 = 7, y_D = 2(5) - 2 = 8 នាំឱ្យ D(7, 8) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ចំណុចកណ្តាល AD: ((1 + 7)/2, (2 + 8)/2) = (4, 5) = B (ពិត) (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12243, 'គេមានរង្វង់ C កំណត់ដោយសមីការវ៉ិចទ័រ \(|\vec{r} - \vec{c}| = 5\) ដែល \(\vec{c} = (2,\, 3)\)។
ក. បង្ហាញថាសមីការពិជគណិតនៃរង្វង់គឺ \((x - 2)^2 + (y - 3)^2 = 25\)។
ខ. ពិនិត្យថាតើចំណុច \(P(5,\, 7)\) ស្ថិតនៅលើរង្វង់ C ដែរឬទេ? បើស្ថិតនៅ ចូរសរសេរសមីការបន្ទាត់ប៉ះរង្វង់ត្រង់ P។', NULL, '[]', 0, NULL, 5, 'writing', 'លើកជាការេ: |\vec{r} - \vec{c}|^2 = 25 <=> (x - 2)^2 + (y - 3)^2 = 25 (ពិត) (1.5 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ចំណុច P(5, 7): (5 - 2)^2 + (7 - 3)^2 = 3^2 + 4^2 = 25 នាំឱ្យ P ស្ថិតនៅលើរង្វង់ (1 ពិន្ទុ)
វ៉ិចទ័រណរម៉ាល់នៃបន្ទាត់ប៉ះ: \vec{n} = \vec{CP} = (5 - 2, 7 - 3) = (3, 4) (1 ពិន្ទុ)
សមីការបន្ទាត់ប៉ះ: 3(x - 5) + 4(y - 7) = 0 <=> 3x + 4y - 43 = 0 (1.5 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12244, 'អង្គធាតុមួយទម្ងន់ \(P = 100\text{ N}\) ត្រូវបានព្យួរដោយខ្សែពីរ AC និង BC ភ្ជាប់ទៅពិដានផ្ដេកត្រង់ A និង B។ ខ្សែ AC បង្កើតមុំ \(30^\circ\) និងខ្សែ BC បង្កើតមុំ \(60^\circ\) ធៀបនឹងពិដានផ្ដេក (មុំត្រង់ C គឺ 90 ដឺក្រេ)។
ក. សរសេរលក្ខខណ្ឌលំនឹងកម្លាំងត្រង់ចំណុច C តាមទិសដេក និងទិសឈរ។
ខ. គណនាកម្លាំងតំណឹង \(T_1\) ក្នុងខ្សែ AC និង \(T_2\) ក្នុងខ្សែ BC។', NULL, '[]', 0, NULL, 5, 'writing', 'លំនឹងទិសដេក: T_1 \cos 30° = T_2 \cos 60° <=> T_1(\sqrt{3}/2) = T_2(1/2) <=> T_2 = T_1\sqrt{3} (1.5 ពិន្ទុ)
លំនឹងទិសឈរ: T_1 \sin 30° + T_2 \sin 60° = P = 100 (1.5 ពិន្ទុ)
ជំនួស T_2: T_1(1/2) + (T_1\sqrt{3})(\sqrt{3}/2) = 100 <=> 2T_1 = 100 នាំឱ្យ T_1 = 50 N (1 ពិន្ទុ)
ទាញរក T_2: T_2 = 50\sqrt{3} ≈ 86.6 N (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12245, 'ក្នុងត្រីកោណ ABC គេយក O ជាគល់នៃប្លង់ និង \(A(\vec{a}),\, B(\vec{b}),\, C(\vec{c})\)។ ចំណុច A'' ជាចំណុចកណ្តាលនៃ BC។
ក. សរសេរវ៉ិចទ័រទីតាំង \(\vec{a}\''\) នៃ A'' ជាអនុគមន៍នៃ \(\vec{b}\) និង \(\vec{c}\)។
ខ. ចំណុច G ចែកមេដ្យាន AA'' ខាងក្នុងតាមផលធៀប \(AG : GA\'' = 2 : 1\)។ រកវ៉ិចទ័រទីតាំង \(\vec{g}\) និងទាញសន្និដ្ឋាន។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរវ៉ិចទ័រទីតាំងចំណុចកណ្តាល A'': \vec{a}'' = (\vec{b} + \vec{c})/2 (1.5 ពិន្ទុ)
រូបមន្តចំណុចចែកក្នុងផលធៀប 2:1: \vec{g} = \dfrac{2\vec{a}'' + 1\vec{a}}{2 + 1} (1.5 ពិន្ទុ)
ជំនួស \vec{a}'': \vec{g} = \dfrac{2((\vec{b} + \vec{c})/2) + \vec{a}}{3} = \dfrac{\vec{a} + \vec{b} + \vec{c}}{3} (1 ពិន្ទុ)
សន្និដ្ឋាន: G គឺជាទីប្រជុំទម្ងន់នៃត្រីកោណ ABC ដែលចែកមេដ្យានតាមផលធៀប 2:1 (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'hard', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12246, 'PISA នាវាចរណ៍ឆ្លងទន្លេ: ទូកចម្លងមួយបើកបរឆ្លងទន្លេទទឹង \(200\text{ m}\) ដោយល្បឿន \(v_b = 5\text{ m/s}\) តម្រង់កាត់កែងនឹងច្រាំងទន្លេ។ ចរន្តទឹកហូរតាមបណ្តោយច្រាំងដោយល្បឿន \(v_r = 3.75\text{ m/s}\)។
ក. គណនារយៈពេលដែលទូកចំណាយដើម្បីទៅដល់ត្រើយម្ខាងទៀត។
ខ. គណនាចម្ងាយដែលទូករសាត់តាមបណ្តោយចរន្តទឹកទន្លេ។
គ. គណនាល្បឿនផ្គួបពិតប្រាកដនៃទូកធៀបនឹងច្រាំង និងចម្ងាយសរុបដែលទូកបានធ្វើដំណើរកាត់ទឹក។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនារយៈពេលឆ្លងទន្លេ: t = 200 / 5 = 40 វិនាទី (1.5 ពិន្ទុ)
គណនាចម្ងាយរសាត់: d_drift = v_r * t = 3.75 * 40 = 150 m (1.5 ពិន្ទុ)
គណនាល្បឿនផ្គួប: v = \sqrt{5^2 + 3.75^2} = \sqrt{25 + 14.0625} = \sqrt{39.0625} = 6.25 m/s (1 ពិន្ទុ)
គណនាចម្ងាយសរុប: d_total = v * t = 6.25 * 40 = 250 m (ឬ \sqrt{200^2 + 150^2} = 250 m) (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12247, 'PISA ការអូសរទេះទំនិញលើជម្រាល: កម្មករម្នាក់ទាញរទេះផ្ទុកទំនិញឡើងលើផ្លូវជម្រាលភ្នំដែលមានមុំទេរ \(30^\circ\)។ ទម្ងន់សរុបនៃរទេះគឺ \(P = 1\,200\text{ N}\)។
ក. គណនាសមាសភាគកម្លាំងទម្ងន់ទាញចុះស្របតាមជម្រាល \(P_{\parallel} = P \sin 30^\circ\)។
ខ. គណនាសមាសភាគកម្លាំងទម្ងន់សង្កត់កែងលើផ្ទៃជម្រាល \(P_{\perp} = P \cos 30^\circ\) (យក \(\cos 30^\circ \approx 0.866\))។
គ. បើមិនគិតកម្លាំងកកិត តើកម្មករត្រូវបញ្ចេញកម្លាំងទាញ \(F\) ស្របនឹងជម្រាលយ៉ាងហោចណាស់ប៉ុន្មានដើម្បីអូសរទេះឡើងលើដោយល្បឿនថេរ?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា P_parallel = 1200 * \sin 30° = 1200 * 0.5 = 600 N (1.5 ពិន្ទុ)
គណនា P_perp = 1200 * \cos 30° = 1200 * 0.866 = 1039.2 N (1.5 ពិន្ទុ)
ពន្យល់លក្ខខណ្ឌល្បឿនថេរ: ផលបូកកម្លាំងតាមទិសជម្រាលស្មើ 0: F - P_parallel = 0 (1 ពិន្ទុ)
ទាញរកកម្លាំងទាញ: F = P_parallel = 600 N (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12248, 'PISA សន្សំសំចៃថាមពល និងកម្មន្ត: ក្នុងការដឹកជញ្ជូនសម្ភារសំណង់ កម្មករម្នាក់ត្រូវរុញរទេះដោយកម្លាំង \(F = 150\text{ N}\) បានចម្ងាយ \(d = 40\text{ m}\)។
ក. គណនាកម្មន្ត W ប្រសិនបើគាត់រុញរទេះស្របតាមទិសដេក (\(\theta = 0^\circ\))។
ខ. គណនាកម្មន្ត W ប្រសិនបើគាត់ទាញខ្សែពួរដែលបង្កើតបានមុំ \(\theta = 45^\circ\) ធៀបនឹងដីផ្ដេក (យក \(\cos 45^\circ \approx 0.707\))។
គ. តើវិធីណាដែលផ្តល់កម្មន្តទៅលើការរំកិលរទេះបានច្រើនជាង និងច្រើនជាងប៉ុន្មានហ្ស៊ូល?', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា W_1 (មុំ 0°): W_1 = 150 * 40 * 1 = 6000 J = 6 kJ (1.5 ពិន្ទុ)
គណនា W_2 (មុំ 45°): W_2 = 150 * 40 * 0.707 = 4242 J ≈ 4.24 kJ (1.5 ពិន្ទុ)
ប្រៀបធៀប: វិធីទី 1 (មុំ 0°) ផ្តល់កម្មន្តច្រើនជាងវិធីទី 2 (1 ពិន្ទុ)
គណនាផលសង: 6000 - 4242 = 1758 J (ច្រើនជាង 1758 J) (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12249, 'PISA ប្រព័ន្ធរ៉ូបូតឃ្លាំងទំនិញ: រ៉ូបូតស្វ័យប្រវត្តមួយក្នុងឃ្លាំងទំនិញផ្លាស់ទីតាមប្លង់កូអរដោនេដេក។ វាចាប់ផ្តើមពីទីតាំង \(A(2,\, 3)\) ទៅយកទំនិញត្រង់ \(B(8,\, 11)\) រួចដឹកបន្តទៅដាក់នៅបញ្ជរ \(C(14,\, 3)\) (គិតជាម៉ែត្រ)។
ក. គណនាវ៉ិចទ័របំលាស់ទី \(\vec{AB}\) និង \(\vec{BC}\)។
ខ. គណនាចម្ងាយផ្លូវសរុប \(AB + BC\) ដែលរ៉ូបូតបានធ្វើដំណើរ។
គ. គណនាប្រវែងនៃវ៉ិចទ័របំលាស់ទីសរុប \(|\vec{AC}|\) ពីចំណុចចាប់ផ្តើម A ដល់ចំណុចបញ្ចប់ C។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា \vec{AB} = (8 - 2, 11 - 3) = (6, 8) និង \vec{BC} = (14 - 8, 3 - 11) = (6, -8) (1.5 ពិន្ទុ)
គណនាប្រវែង: AB = \sqrt{6^2 + 8^2} = 10 m និង BC = \sqrt{6^2 + (-8)^2} = 10 m នាំឱ្យចម្ងាយសរុប = 20 m (1.5 ពិន្ទុ)
គណនា \vec{AC} = \vec{AB} + \vec{BC} = (6 + 6, 8 - 8) = (12, 0) (1 ពិន្ទុ)
គណនាប្រវែងបំលាស់ទីសរុប: |\vec{AC}| = 12 m (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 12250, 'PISA លំនឹងស្ទូចសំណង់: ស្ទូចសំណង់មួយកំពុងទប់ទម្ងន់ធ្នឹមដែក \(P = 8\,000\text{ N}\) ឱ្យនៅនឹងថ្កល់ក្នុងអាកាស។ កម្លាំងទាញរបស់ខ្សែស្ទូចពីរគឺ \(\vec{T}_1\) និង \(\vec{T}_2\) បង្កើតបានមុំ \(45^\circ\) សងខាងធៀបនឹងបន្ទាត់ឈរ (មុំរវាងខ្សែទាំងពីរគឺ \(90^\circ\))។
ក. សរសេរលក្ខខណ្ឌលំនឹងកម្លាំងនៃធ្នឹមដែក។
ខ. គណនាកម្លាំងតំណឹង \(T_1 = T_2 = T\) ក្នុងខ្សែស្ទូចនីមួយៗ (យក \(\cos 45^\circ = \dfrac{\sqrt{2}}{2}\))។
គ. បើខ្សែនីមួយៗទ្រាំទ្រកម្លាំងអតិបរមា 5000 N តើការលើកនេះមានសុវត្ថិភាពឬទេ?', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌលំនឹង: \vec{T}_1 + \vec{T}_2 + \vec{P} = \vec{0} នាំឱ្យផលបូកទិសឈរ 2T \cos 45° = P = 8000 (1.5 ពិន្ទុ)
ដោះស្រាយសមីការ: 2T(\sqrt{2}/2) = 8000 <=> T\sqrt{2} = 8000 នាំឱ្យ T = 4000\sqrt{2} ≈ 5656.85 N (1.5 ពិន្ទុ)
ប្រៀបធៀបកម្លាំងទ្រាំទ្រ: T ≈ 5656.85 N > 5000 N (1 ពិន្ទុ)
សន្និដ្ឋានសុវត្ថិភាព: មិនមានសុវត្ថិភាពឡើយ ព្រោះកម្លាំងតំណឹងជាក់ស្តែងលើសពីកម្រិតកំណត់អតិបរមា (ខ្សែអាចនឹងដាច់) (1 ពិន្ទុ)', 'ការអនុវត្តវ៉ិចទ័រ', 'pisa', 0, '10', 'ការអនុវត្តវ៉ិចទ័រ', 'ជំពូកទី 8 : វ៉ិចទ័រក្នុងប្លង់', NULL, 0);
